/// Copy a single file using the zero-copy cascade in `copy::file_copy`.
fn write_file_payload(
    src_root: &Path,
    dst_root: &Path,
    within: Option<&crate::copy::Within>,
    header: &FileHeader,
    config: &FsSinkConfig,
) -> Result<SinkOutcome> {
