/// into its paths. Bytes the record cannot give back fall to the text.
fn retry_names<'a>(
    failed: impl Iterator<Item = &'a (String, Option<String>)>,
) -> (HashSet<PathBuf>, HashSet<Vec<u8>>) {
    let mut names = HashSet::new();
