        let pass_phase = format!("retry pass {pass} of {total}");
        if let Some(run) = &args.run {
            run.record(blit_core::job_log::EventBody::Phase {
                name: pass_phase.clone(),
                state: blit_core::job_log::PhaseState::Start,
